import { act, cleanup, render, screen, within } from '@testing-library/react'
import { createRef } from 'react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { MobileMainWindow } from './mobile_main_window'

const auth: UseGithubAuthResult = {
    accessToken: null,
    errorMessage: null,
    isAuthenticated: false,
    isLoadingUser: false,
    logout: vi.fn(),
    savePersonalAccessToken: vi.fn(),
    status: 'idle',
    user: null,
}

function renderMobileMainWindow(showNavigationInCards: boolean) {
    const rightPanelContainerRef = createRef<HTMLDivElement>()

    return render(
        <AppThemeProvider>
            <MobileMainWindow
                auth={auth}
                cardNavigation={<nav>Board navigation</nav>}
                isMenuOpen
                leftPanel={<nav>Project navigation</nav>}
                onCloseMenu={vi.fn()}
                rightPanel={<main>Project workspace</main>}
                rightPanelContainerRef={rightPanelContainerRef}
                showNavigationInCards={showNavigationInCards}
            />
        </AppThemeProvider>,
    )
}

describe('MobileMainWindow', () => {
    afterEach(() => {
        cleanup()
        workspaceViewService.setViewMode('cards')
    })

    it('shows navigation in the drawer when requested', () => {
        renderMobileMainWindow(true)

        expect(screen.getByText('Project navigation')).toBeInTheDocument()
        expect(screen.getByText('Project workspace')).toBeInTheDocument()
        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()
    })

    it('pins project status directly above the account footer', () => {
        renderMobileMainWindow(true)

        const status = screen.getByRole('region', { name: 'Project status' })
        const footer = screen.getByRole('contentinfo')
        const separator = status.nextElementSibling

        expect(within(status).getByText('Cards')).toBeInTheDocument()
        expect(within(status).getByText('Local save')).toBeInTheDocument()
        expect(within(status).getByText('Remote push')).toBeInTheDocument()
        expect(within(status).getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()
        expect(within(status).getByRole('button', { name: 'Agent token usage summary' })).toBeInTheDocument()
        expect(within(status).queryByText('Remote control')).toBeNull()
        expect(within(status).queryByText('Caps Lock')).toBeNull()
        expect(separator?.tagName).toBe('HR')
        expect(separator?.nextElementSibling).toBe(footer)
        expect(screen.getByTestId('mobile-navigation-scroll-region')).toHaveStyle({ overflow: 'auto' })
    })

    it('hides navigation without hiding workspace content', () => {
        renderMobileMainWindow(false)

        expect(screen.getByText('Project navigation')).not.toBeVisible()
        expect(screen.getByText('Board navigation')).toBeVisible()
        expect(screen.getByText('Project workspace')).toBeInTheDocument()
    })

    it('shows navigation in text view without rerendering it', () => {
        renderMobileMainWindow(false)
        const navigation = screen.getByText('Project navigation')

        act(() => workspaceViewService.setViewMode('text'))

        expect(screen.getByText('Project navigation')).toBe(navigation)
        expect(navigation).toBeVisible()
        expect(screen.getByText('Board navigation')).not.toBeVisible()
    })
})

import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useEffect, useMemo, useRef } from 'react'
import type { UseGithubAuthResult } from '../auth/use_github_auth'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_ACTIONS_FOLDER,
    DEFAULT_ARCHIVED_FOLDER,
    DEFAULT_PROJECT_FOLDER,
    DEFAULT_RELEASES_FOLDER,
    DEFAULT_STATES,
    defaultColumnAccent,
} from '../data/data_types'
import { dataService } from '../services/data/data_service'
import { dialogService } from '../services/dialog_service'
import { getElectronLifecycleBridge, type ElectronFlushRequest, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'
import { openFilesService } from '../services/open_files_service'
import type { OpenDocument } from '../services/open_files_service'
import { telemetryService } from '../services/telemetry/telemetry_service'
import { workspaceViewService } from '../services/project/workspace_view_service'
import { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'
import { projectPersistenceService } from '../services/project/project_persistence_service'
import { CardView } from './card_view/card_view'
import { MobileCardViewMenu } from './card_view/mobile_card_view_menu'
import { MobileCardView } from './card_view/mobile_card_view'
import { CardActionPopupHost } from './actions/run/popup/card_action_popup_host'
import { stageMarkdownEditors } from '../services/project/markdown_editor_staging'
import { useProjectReference } from './hooks/use_project_reference'
import { TextView } from './text_view/text_view'
import { FileTreeView } from './text_view/file_tree_view'
import { useProjectConfig } from './hooks/use_project_config'
import { useWorkingFolder } from './hooks/use_working_folder'
import { ProjectWorkspaceAvailability } from './project_workspace_availability'
import { MobileLayout } from './shell/mobile_layout'
import { MobileMainWindow } from './shell/mobile_main_window'
import { SplitLayout } from './shell/split_layout'
import { AttachmentChoiceDialog } from './editor/attachment_choice_dialog'

const WORKSPACE_PANEL_PADDING = 3

function openDocumentPath(document: OpenDocument) {
    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath
}

function flushPendingCommits() {
    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })
    })
}

async function flushAndReportPendingCommits(lifecycleBridge: ElectronLifecycleBridge, request: ElectronFlushRequest) {
    try {
        await projectPersistenceService.flushPendingChanges()
        lifecycleBridge.reportFlushResult({ requestId: request.requestId, success: true })
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })
        lifecycleBridge.reportFlushResult({ requestId: request.requestId, success: false })
    }
}

function runWorkspaceEdit(action: () => void, fallbackMessage: string) {
    try {
        action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

interface ProjectWorkspaceProps {
    auth: UseGithubAuthResult
    isMenuOpen: boolean
    onLeftPanelInteraction: () => void
}

export function ProjectWorkspace(props: ProjectWorkspaceProps) {
    const { auth, isMenuOpen, onLeftPanelInteraction } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const project = useProjectReference()
    const projectConfig = useProjectConfig()
    const workingFolder = useWorkingFolder()
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const states = projectConfig?.states ?? DEFAULT_STATES
    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER
    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`
    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`
    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`
    const mobileScrollContainerRef = useRef<HTMLDivElement>(null)
    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)
    const statusColors = useMemo(() => new Map(
        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),
    ), [states])

    useEffect(() => {
        onLeftPanelInteractionRef.current = onLeftPanelInteraction
    })

    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createFolder(parentDirectory, name)
    }, [])

    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createMarkdownFile(parentDirectory, name)
    }, [])

    const handleDeleteFile = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFile(path)
            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)
            if (document) openFilesService.closeDocument(document)
            workspaceViewService.clearSelectedPath(path)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })
            throw error
        }
    }, [])

    const handleDeleteFolder = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFolder(path)
            const folderPrefix = `${path.replace(/\/+$/u, '')}/`
            const documents = openFilesService.getSnapshot().documents
            for (const document of documents) {
                const openPath = openDocumentPath(document)
                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)
            }
            const selectedPath = workspaceViewService.getSnapshot().selectedPath
            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })
            throw error
        }
    }, [])

    useEffect(() => {
        const handleBeforeUnload = (event: BeforeUnloadEvent) => {
            const staged = stageMarkdownEditors()
            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()
            // In Electron, vetoing beforeunload silently cancels the window close (no confirm
            // dialog), leaving the app unclosable. The main process flushes pending commits on
            // quit instead, so only prompt in a plain browser build.
            if ((!staged || hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {
                event.preventDefault()
                event.returnValue = ''
            }

            flushPendingCommits()
        }

        const handleVisibilityChange = () => {
            if (document.visibilityState === 'hidden') flushPendingCommits()
        }

        const handleBlur = () => flushPendingCommits()

        const handlePageHide = () => flushPendingCommits()

        document.addEventListener('visibilitychange', handleVisibilityChange)
        window.addEventListener('beforeunload', handleBeforeUnload)
        window.addEventListener('blur', handleBlur)
        window.addEventListener('pagehide', handlePageHide)

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange)
            window.removeEventListener('beforeunload', handleBeforeUnload)
            window.removeEventListener('blur', handleBlur)
            window.removeEventListener('pagehide', handlePageHide)
        }
    }, [])

    useEffect(() => {
        const lifecycleBridge = getElectronLifecycleBridge()
        if (!lifecycleBridge) return undefined

        return lifecycleBridge.onFlushRequested((request) => {
            void flushAndReportPendingCommits(lifecycleBridge, request)
        })
    }, [])

    useEffect(() => {
        const handleNavigationOpen = (event: Event) => {
            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail
            // Reveal the card/file without changing the current view mode: highlight it in card view
            // and open it in the service-owned text-view tabs.
            workspaceViewService.selectPath(path)
            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
            telemetryService.trackEvent('navigation')
        }

        workspaceNavigationService.addEventListener('open', handleNavigationOpen)

        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)
    }, [])

    const fileTree = (
        <Box
            aria-label="File tree"
            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}
        >
            <FileTreeView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                onCreateFolder={handleCreateFolder}
                onCreateMarkdownFile={handleCreateMarkdownFile}
                onDeleteFile={handleDeleteFile}
                onDeleteFolder={handleDeleteFolder}
                onLeftPanelInteraction={onLeftPanelInteraction}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                statusColors={statusColors}
                workingFolder={workingFolder}
            />
        </Box>
    )
    const textView = (
        <Paper
            elevation={0}
            sx={{
                border: 1,
                borderColor: 'divider',
                borderRadius: 2,
                boxSizing: 'border-box',
                display: 'flex',
                height: '100%',
                minHeight: 0,
                overflow: 'hidden',
                p: WORKSPACE_PANEL_PADDING,
            }}
        >
            <TextView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                states={states}
            />
        </Paper>
    )

    const workspace = (
        <ProjectWorkspaceAvailability>
            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}
            {isMobile ? (
                <MobileCardView cardTypes={cardTypes} states={states} statusColors={statusColors} />
            ) : (
                <CardView cardTypes={cardTypes} states={states} statusColors={statusColors} />
            )}
            <CardActionPopupHost />
        </ProjectWorkspaceAvailability>
    )
    const navigation = project ? fileTree : (
        <Box sx={{ p: 2 }}>
            <Typography color="text.secondary" variant="body2">
                No project navigation available.
            </Typography>
        </Box>
    )

    return (
        <Box
            aria-label="Project workspace"
            component="section"
            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: isMobile ? 'unset' : 'hidden' }}
        >
            {isMobile ? (
                <MobileMainWindow
                    auth={auth}
                    cardNavigation={project ? <MobileCardViewMenu onSelected={onLeftPanelInteraction} states={states} /> : null}
                    isMenuOpen={isMenuOpen}
                    leftPanel={navigation}
                    onCloseMenu={onLeftPanelInteraction}
                    rightPanel={workspace}
                    rightPanelContainerRef={mobileScrollContainerRef}
                    showNavigationInCards={!project}
                />
            ) : workspace}
            <AttachmentChoiceDialog />
        </Box>
    )
}

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type { Card } from '../../data/data_types'
import { dataService } from '../../services/data/data_service'
import { mobileCardViewService } from '../../services/project/mobile_card_view_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { MobileCardViewMenu } from './mobile_card_view_menu'

function card(id: string, status: string): Card {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        content: '',
        header: {
            affects: [], after: null, agentLogReferences: [], author: null, id, internalId: id, owner: null,
            policy: {}, references: [], status, title: id,
        },
        hasFrontmatter:true,
        isActive: true,
        path: `design/${id}.md`,
    }
}

describe('MobileCardViewMenu', () => {
    beforeEach(() => {
        vi.spyOn(dataService, 'getState').mockReturnValue({
            project: { branch: 'main', id: 'project', rootPath: 'C:\\project' },
            runningAgents: [],
            snapshot: { activeCards: [card('F-1', 'todo'), card('F-2', 'done')], backgroundCards: [], repositoryFiles: [], workingFolder: 'design' },
        })
        mobileCardViewService.selectVisibleColumn([])
    })

    afterEach(() => {
        cleanup()
        vi.restoreAllMocks()
    })

    it('lists visible columns, selects one, and closes drawer', () => {
        const onSelected = vi.fn()
        render(
            <AppThemeProvider>
                <MobileCardViewMenu
                    onSelected={onSelected}
                    states={[
                        { alwaysVisible: false, state: 'todo' },
                        { alwaysVisible: false, state: 'done' },
                        { alwaysVisible: false, state: 'hidden' },
                    ]}
                />
            </AppThemeProvider>,
        )

        expect(screen.getByRole('menuitem', { name: 'todo' })).toHaveClass('Mui-selected')
        expect(screen.queryByRole('menuitem', { name: 'hidden' })).not.toBeInTheDocument()

        fireEvent.click(screen.getByRole('menuitem', { name: 'done' }))

        expect(mobileCardViewService.getSnapshot().selectedColumnStatus).toBe('done')
        expect(onSelected).toHaveBeenCalledOnce()
        act(() => mobileCardViewService.selectVisibleColumn([]))
    })
})

import { Box, MenuItem, MenuList, Typography } from '@mui/material'
import type { MouseEvent } from 'react'
import type { StateConfig } from '../../data/data_types'
import { mobileCardViewService } from '../../services/project/mobile_card_view_service'
import { useCardViewColumns } from './use_card_view_columns'
import { useMobileCardViewColumn } from './use_mobile_card_view_column'

interface MobileCardViewMenuProps {
    onSelected: () => void
    states: StateConfig[]
}

/** Visible board-column choices for mobile hamburger drawer. */
export function MobileCardViewMenu(props: MobileCardViewMenuProps) {
    const { onSelected, states } = props
    const columns = useCardViewColumns(states)
    const selectedColumn = useMobileCardViewColumn(columns)

    const handleSelectColumn = (event: MouseEvent<HTMLLIElement>) => {
        const status = event.currentTarget.dataset.status
        if (status === undefined) throw new Error('Missing mobile card column status')

        mobileCardViewService.selectColumn(status)
        onSelected()
    }

    return (
        <Box aria-label="Board columns">
            <Typography sx={{ color: 'text.secondary', fontWeight: 600, px: 2, pb: 0.5, pt: 1.5 }} variant="body2">
                Board columns
            </Typography>
            <MenuList>
                {columns.map(({ color, status }) => (
                    <MenuItem
                        data-status={status}
                        key={status}
                        onClick={handleSelectColumn}
                        selected={selectedColumn?.status === status}
                    >
                        <Box sx={{ bgcolor: color, borderRadius: '3px', height: 8, mr: 1, width: 8 }} />
                        {status || 'Unassigned'}
                    </MenuItem>
                ))}
            </MenuList>
        </Box>
    )
}

import { Box } from '@mui/material'
import type { ReactNode } from 'react'
import { useEffect, useRef } from 'react'
import { dialogService } from '../../services/dialog_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'

interface MobileLayoutProps {
    content: ReactNode
}

/** Mobile body layout: a single panel that is only visible while the text view mode is active. */
export function MobileLayout(props: MobileLayoutProps) {
    const { content } = props
    const containerRef = useRef<HTMLDivElement>(null)
    const missingContainerReportedRef = useRef(false)

    useEffect(() => {
        const updateVisibility = () => {
            const container = containerRef.current
            if (!container) {
                if (!missingContainerReportedRef.current) {
                    missingContainerReportedRef.current = true
                    dialogService.error(new Error('Missing mobile layout container'), {fallbackMessage: 'Mobile layout could not be displayed'})
                }
                return
            }

            container.style.display = workspaceViewService.getSnapshot().viewMode === 'text' ? 'flex' : 'none'
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [])

    return (
        <Box ref={containerRef} sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'auto' }}>
            <Box sx={{ flex: 1, minWidth: 0, overflow: 'auto' }}>
                {content}
            </Box>
        </Box>
    )
}

import { Box, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { navigateTo, useAppLocation } from '../../app/app_navigation'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { ConfigPage } from '../config/config_page'
import { useProjectReference } from '../hooks/use_project_reference'
import { ProjectWorkspace } from '../project_workspace'
import { createSearchRegexpAgent, isSearchRegexpAgentAvailable } from '../../services/search/search_regexp_agent'
import { AppMenu } from './menu/app_menu'
import { SearchControl } from './search/search_control'
import { StatusBar } from './status_bar'

interface MainWindowProps {
    auth: UseGithubAuthResult
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const project = useProjectReference()
    const isConfigOpen = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            <ProjectWorkspace
                auth={auth}
                isMenuOpen={isMenuOpen}
                key={project ? `${project.id}:${project.branch}` : 'no-project'}
                onLeftPanelInteraction={handleCloseMenu}
            />
            {!isMobile ? <StatusBar /> : null}
            {isConfigOpen ? <ConfigPage hash={location.hash} /> : null}
        </Box>
    )
}
